// Database access through libSQL: a local SQLite file in development, Turso in production.

import { fileURLToPath } from 'node:url'
import { createClient, type Client } from '@libsql/client'
import { drizzle, type LibSQLDatabase } from 'drizzle-orm/libsql'
import { migrate } from 'drizzle-orm/libsql/migrator'
import * as schema from './schema.js'

export type Database = LibSQLDatabase<typeof schema>

/** drizzle/, generated by drizzle-kit: the same path from src/db/ (dev, tests) and dist/db/. */
const MIGRATIONS_FOLDER = fileURLToPath(new URL('../../drizzle', import.meta.url))

/**
 * Opens the database at `url` (`libsql://…` for Turso, otherwise a SQLite file, `file:` optional)
 * and applies pending migrations.
 *
 * Outside transactions, the libSQL client sends each statement to Turso as its own HTTP request,
 * opening and closing its stream in it, so one client serves every request: there's no long-lived
 * stream to expire.
 */
export async function openDatabase(
  url: string,
  authToken?: string,
): Promise<{ client: Client; db: Database }> {
  const client = createClient({
    url: /^[a-z][a-z0-9+.-]*:/i.test(url) ? url : `file:${url}`,
    authToken: authToken || undefined,
  })
  const db = drizzle(client, { schema })
  try {
    await migrate(db, { migrationsFolder: MIGRATIONS_FOLDER })
  } catch (err) {
    client.close()
    throw new Error(`Failed to migrate the database at ${url}`, { cause: err })
  }
  return { client, db }
}

/** The row of a query that always returns one, like `INSERT … RETURNING`. */
export function one<T>(rows: T[]): T {
  const [row] = rows
  if (row === undefined) throw new Error('The query returned no rows')
  return row
}
